import * as React from 'react';
import OutlinedInput from '@tecton-mui/ui/OutlinedInput';
import InputLabel from '@tecton-mui/ui/InputLabel';
import MenuItem from '@tecton-mui/ui/MenuItem';
import FormControl from '@tecton-mui/ui/FormControl';
import ListItemText from '@tecton-mui/ui/ListItemText';
import Select, { type SelectChangeEvent } from '@tecton-mui/ui/Select';
import Icon, { type IconProps } from '@tecton-mui/ui/Icon';

function CheckBoxIcon(props: Omit<IconProps, 'name'>) {
  return <Icon name="checkbox-checked" variant="filled" {...props} />;
}

function CheckBoxOutlineBlankIcon(props: Omit<IconProps, 'name'>) {
  return <Icon name="checkbox-unchecked" {...props} />;
}

const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
  slotProps: {
    paper: {
      style: {
        maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
        width: 250,
      },
    },
  },
};

const names = [
  'Oliver Hansen',
  'Van Henry',
  'April Tucker',
  'Ralph Hubbard',
  'Omar Alexander',
  'Carlos Abbott',
  'Miriam Wagner',
  'Bradley Wilkerson',
  'Virginia Andrews',
  'Kelly Snyder',
];

export default function MultipleSelectCheckmarks() {
  const [personName, setPersonName] = React.useState<string[]>([]);

  const handleChange = (event: SelectChangeEvent<typeof personName>) => {
    const {
      target: { value },
    } = event;
    setPersonName(
      // On autofill we get a stringified value.
      typeof value === 'string' ? value.split(',') : value,
    );
  };

  return (
    <div>
      <FormControl sx={{ m: 1, width: 300 }}>
        <InputLabel id="demo-multiple-checkbox-label">Tag</InputLabel>
        <Select
          labelId="demo-multiple-checkbox-label"
          id="demo-multiple-checkbox"
          multiple
          value={personName}
          onChange={handleChange}
          input={<OutlinedInput label="Tag" />}
          renderValue={(selected) => selected.join(', ')}
          MenuProps={MenuProps}
        >
          {names.map((name) => {
            const selected = personName.includes(name);
            const SelectionIcon = selected ? CheckBoxIcon : CheckBoxOutlineBlankIcon;

            return (
              <MenuItem key={name} value={name}>
                <SelectionIcon
                  size="small"
                  style={{ marginRight: 8, padding: 2, boxSizing: 'content-box' }}
                />
                <ListItemText primary={name} />
              </MenuItem>
            );
          })}
        </Select>
      </FormControl>
    </div>
  );
}
